omar (sdk): Python sample (compact):

```python
from redwood import Client, TransientError
client = Client()

async def pages(prompt):
    async for s in client.stream_responses(model=\"open-3\", input=prompt):
        try:
            async for p in s.paginate():
                yield p
        except TransientError:
            token = getattr(s, "retry_token", None)
            cursor = await client.get_cursor_from_retry(token)
            async for p in client.resume_pages(cursor):
                yield p
```

omar (sdk): TypeScript sample (short):

```ts
import Redwood from '@redwood/inference'
const c = new Redwood()

export async function* pagesWithRetry(prompt: string) {
  for await (const s of c.streamResponses({ model: 'open-3', input: prompt })) {
    try {
      for await (const p of s.paginate()) yield p
    } catch {
      const token = (s as any).retryToken
      const cursor = await c.getCursorFromRetry(token)
      for await (const p of c.resumePages(cursor)) yield p
    }
  }
}
```

rachel (eng): Go SDK uses ResumeStream(cursor) not resumePages; show that pattern.

omar (sdk): Go sample: concise resume-stream pattern.

```go
package examples
import (
  \"context\"
  rw \"github.com/redwood-inference/go-sdk\"
)

func StreamPages(ctx context.Context, prompt string) <-chan rw.Page {
  out := make(chan rw.Page)
  go func() {
    defer close(out)
    c := rw.NewClient()
    st, _ := c.StreamResponses(ctx, rw.StreamParams{Model: \"open-3\", Input: prompt})
    for st.Next() {
      pages, err := st.Pages()
      if err != nil {
        token, _ := st.RetryToken()
        cursor, _ := c.GetCursorFromRetry(ctx, token)
        resumed := c.ResumeStream(ctx, cursor)
        for resumed.Next() {
          for _, p := range resumed.Pages() { out <- p }
        }
        return
      }
      for _, p := range pages { out <- p }
    }
  }()
  return out
}
```

